import { esc } from "./utils.js";
export function timeline(items) {
  return `<div class="timeline" data-transmission><svg class="transmission-rail" preserveAspectRatio="none" viewBox="0 0 28 1000" aria-hidden="true"><path class="rail" d="M9 0v1000M19 0v1000"/><path class="signal-path" d="M14 0v1000"/></svg>${items.map((item) => `<article class="timeline-entry"><span class="timeline-node" aria-hidden="true"></span><div class="timeline-date mono">${esc(item.date)}</div><div class="timeline-content"><h3>${esc(item.title)}</h3><p class="organization">${esc(item.organization)}</p>${item.points.length ? `<ul>${item.points.map((p) => `<li>${esc(p)}</li>`).join("")}</ul>` : ""}</div></article>`).join("")}</div>`;
}
